-- Hand-authored player descriptions (ADR 0009 Phase 4, Players.Description).
-- One-time data load, not application code — the running app only ever serves this
-- persisted text (see PlayerSummaryRow.Description / player_summary(steamid)).
-- Authored by working through scripts/player-narrative-facts.sql output for every
-- player with 20+ games (291 players as of authoring); everyone else gets the
-- generic fallback appended at the end of this file.
--
-- Run once against a target .duckdb file (local dev or production) after the
-- Description column exists (Schema.sql runs automatically on backend startup):
--   duckdb <path-to-.duckdb> < scripts/player-descriptions.sql
--
-- Idempotent: safe to re-run, later runs simply overwrite with the same text.

UPDATE Players SET Description = 'A true projectile main, splitting time almost evenly between Demoman and Soldier, with a fair amount of Scout in the mix too. Airshots are a real strength on both projectile classes, landing in the upper tier of the leaderboard for each. Playing since 2013, though at a somewhat lower rate than in years past.' WHERE SteamID = 76561198080441494;
UPDATE Players SET Description = 'Primarily a Soldier player with serious airshot pedigree, among the best on the leaderboard for it, backed up by strong damage output on the class too. Also puts in real time on Sniper and Demoman rather than being a one-trick pony. A fixture since 2017 and still one of the most active players around.' WHERE SteamID = 76561198271775400;
UPDATE Players SET Description = 'A Soldier specialist through and through, with close to 60% of games on the class, and it shows: airshot numbers among the best on record. Damage output is elite on both Soldier and the Scout games mixed in. Around since 2014, though these days plays a fraction of what they once did.' WHERE SteamID = 76561198056403602;
UPDATE Players SET Description = 'An out-and-out Soldier main, nearly 70% of games on the class, and one of the best airshotters on record, alongside standout damage numbers on both Soldier and Scout. Playing since 2014, with a noticeably quieter pace in recent times.' WHERE SteamID = 76561198107170907;
UPDATE Players SET Description = 'Splits time between Demoman and Soldier as a genuine dual-projectile threat, with a handful of Medic games rounding things out. Airshot accuracy on Soldier sits comfortably above most of the field. Around since 2014, but games have grown much rarer lately.' WHERE SteamID = 76561198087848782;
UPDATE Players SET Description = 'An unusual mix: elite damage output on Scout paired with genuinely strong Medic play, including healing and uber numbers well above most full-time medics. Not a one-class player by any means. On the scene since 2015, playing somewhat less than in their peak years.' WHERE SteamID = 76561198112417529;
UPDATE Players SET Description = 'A genuine all-rounder, splitting substantial time across Demoman, Scout and Soldier without leaning hard on any one of them, closer to a jack-of-all-trades than a specialist. Playing since 2014, at a somewhat reduced pace compared to their busiest years.' WHERE SteamID = 76561198143358434;
UPDATE Players SET Description = 'A Soldier-first player with real range: the airshot numbers on Demoman are near the top of the leaderboard, and Soldier damage output isn''t far behind. One of the longest-tenured players still going, active since 2013 and still playing regularly.' WHERE SteamID = 76561198051608840;
