-- Fallback for every player below the 20-game threshold (or newly added since) —
-- honest placeholder rather than a fabricated narrative for players with too little
-- history to say anything real. Re-run this block any time new low-signal players
-- are added; it only touches rows that still have no Description.
UPDATE Players p
SET Description = 'Only ' || g.NumberOfGames || CASE WHEN g.NumberOfGames = 1 THEN ' game' ELSE ' games' END || ' recorded so far, too early to characterize their playstyle.'
FROM (SELECT SteamID, COUNT(DISTINCT GameID) AS NumberOfGames FROM PlayerStats GROUP BY SteamID) g
WHERE p.SteamID = g.SteamID AND p.Description IS NULL;

UPDATE Players SET Description = 'No games recorded yet.' WHERE Description IS NULL;
